mapper.sql:
WHERE u.tenant_id = #{tenantId}

    AND (u.username ILIKE '%' || #{keyword} || '%' OR u.display_name ILIKE '%' || #{keyword} || '%')


    AND EXISTS (SELECT 1 FROM app_user_role ur WHERE ur.user_id = u.id AND ur.role_id = #{roleId})

AND u.enabled
AND NOT u.enabled
AND u.locked_until > #{now}
